// The type the hook receives must say it is the turn's total, so the signature needs no trip to the orchestrator.
const reportTurnUsage: NonNullable<OrchestratorHooks['afterModelResponse']> = async (
  _session,
  _responseText,
  totalUsage?: TurnUsage
) => {
  void totalUsage;
};

// Issue #93: the public API must name what afterModelResponse's usage argument is, so a deployer can type their audit hook from it.
it("types afterModelResponse's usage argument as the turn total, exported from the public API", () => {
  expect(typeof reportTurnUsage).toBe('function');
});

